#!/usr/bin/env python3
"""FS3 v209 - perspective and scale (Silvio, 10.10.2026).

    Scale      Two scales: up to 40 m a hull keeps its real length
               (fighters, bombers); every metre beyond counts 0.2
               (CAP_L0, CAP_K). Orion 438 m, Ravana 501 m, Colossus 1265 m.
    Camera     Further out: CAM_BASE_Z 0.35 (overview Z three times that).
    3D         A real perspective of 40 degrees, the camera looking straight
               down; capital ships are sunk by half their thickness, so the
               side facing the camera lies in the play plane and fighters
               fly over them.
    Tempo      Small craft and every round fly TEMPO_K = 1/0.35 faster, so
               on the screen they move as in v207. Rounds keep their flight
               time (reach as in v207 on the screen, turrets included).
               Capital ships, beams and scripted runs keep their pace.
    Overlays   Names, bars, subsystem marks, chevrons, tag and scan marks,
               the hold ring and pickups on the screen in a fixed size.
               Shots, sparks, trails and beams at their v207 size on the
               screen (fxG), missiles and bombs at half of that (ordG).
    On hulls   Beam turrets, hits, blasts, damage effects, scorch, reactor
               and subsystem marks go where the model is drawn (hullPt);
               shield hits from the real eye (f3dShRay).
    Sound      Distances on the screen (SND_NEAR/SND_FALL / CAM_BASE_Z).
    Stars      Parallax times CAM_BASE_Z. Depth: near plane D*0.15.

Needs v208. Edits src/10_core.js, 12_audio.js, 20_render.js, 30_waves.js,
40_world.js, 50_combat.js, 55_arms.js, 57_turrets.js, 59_field3d.js,
60_effects.js, 70_ui.js and the tests callsim.js, docksim.js, hudsim.js,
mechsim.js, pausesim.js, ramsim.js, shipsim.js, wpnsim.js, fieldsim.js.
No new model files. Run assemble.py 209 afterwards.
"""
import base64
import os
import sys

if not os.path.exists("src/40_world.js"):
    sys.exit("Abbruch: erst v208 einspielen.")
if "function worldForWave" not in open("src/40_world.js", encoding="utf-8").read():
    sys.exit("Abbruch: erst v208 einspielen.")
if "const TEMPO_K" in open("src/10_core.js", encoding="utf-8").read():
    sys.exit("v209 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
